sourceContents:
# October delivery trigger: Cloud Storage object.v1.finalized (Eventarc) -> this workflow -> Cloud Run job.
# Only gs://<bucket>/requests/<run_id>/run_manifest.json starts work; every other object (reports,
# sources, outputs) is ignored. The event's exact generation is passed through; the job never reads
# a "latest" request. Submission is not success: the run's status object is the durable outcome.
# The job is configured with --max-retries 0 (deploy_delivery.sh): a failed run is never resumed;
# retry = new run ID. Duplicate events for the same generation return the original status.
main:
  params: [event]
  steps:
    - init:
        assign:
          - project: ${sys.get_env("GOOGLE_CLOUD_PROJECT_ID")}
          - location: ${sys.get_env("DELIVERY_LOCATION")}
          - job: ${sys.get_env("DELIVERY_JOB")}
          # Container overrides REPLACE the job's args, so the full argv is rebuilt here from the
          # configured deployment values (never from the event) plus the event's exact request.
          - output_root: ${sys.get_env("DELIVERY_OUTPUT_ROOT")}
          - release_namespace: ${sys.get_env("DELIVERY_RELEASE_NAMESPACE")}
          - image_uri: ${sys.get_env("DELIVERY_IMAGE_URI")}
          - bucket: ${event.data.bucket}
          - name: ${event.data.name}
          - generation: ${string(event.data.generation)}
    - filter:
        switch:
          - condition: ${not(text.match_regex(name, "^requests/[a-z0-9][a-z0-9._-]{2,62}/run_manifest\\.json$"))}
            return: ${"ignored " + name}
          - condition: ${not(text.match_regex(generation, "^[1-9][0-9]*$"))}
            raise: ${"event without an exact generation for " + name}
    - run_job:
        call: googleapis.run.v2.projects.locations.jobs.run
        args:
          name: ${"projects/" + project + "/locations/" + location + "/jobs/" + job}
          body:
            overrides:
              containerOverrides:
                - args:
                    - "-m"
                    - "cloud.orchestrator.delivery_job"
                    - "run"
                    - "--request-uri"
                    - ${"gs://" + bucket + "/" + name}
                    - "--request-generation"
                    - ${generation}
                    - "--output-root"
                    - ${output_root}
                    - "--release-namespace"
                    - ${release_namespace}
                    - "--image-uri"
                    - ${image_uri}
          connector_params:
            # Submit only: the run's status object (runs/<run_id>/run_status.json) is the durable outcome.
            # Polling the long-running operation would need project-level run.operations.get.
            skip_polling: true
        result: execution
    - done:
        return: ${execution}
